// Compendium Bilingual Data for Section 5 (Minisubmarinos M5-M9)
window.COMP_MIDGET_HTML = {
  es: "<div id=\"comp-sec-midget\" class=\"compendium-section\" data-comp-sec=\"midget\" style=\"margin-bottom:28px;\">\n        <h3 style=\"border-bottom:2px solid #38bdf8; padding-bottom:6px; color:#38bdf8; font-family:'Cinzel', serif; font-size:1.15rem; display:flex; align-items:center; gap:8px;\">\n          <span>\u2693</span> <span>5. OPERACIONES ESPECIALES DE MINISUBMARINOS KO-HYOTEKI (CHARTS M5 A M9)</span>\n        </h3>\n\n\n\n                <!-- OCR TRANSCRIBED OFFICIAL CHARTS M5 TO M7 -->\n        <div style=\"margin-bottom:16px;\">\n          <div class=\"ocr-board-m5-m7\" style=\"background:#0f172a; border:2px solid #38bdf8; border-radius:10px; padding:16px; color:#f1f5f9; font-family:'Segoe UI', Roboto, sans-serif; box-shadow:0 8px 30px rgba(0,0,0,0.7);\">\n  <!-- HEADER -->\n  <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid #38bdf8; padding-bottom:8px; margin-bottom:14px; flex-wrap:wrap; gap:10px;\">\n    <div style=\"display:flex; align-items:center; gap:12px;\">\n      <span style=\"background:#0284c7; color:#fff; font-size:0.86rem; font-weight:900; padding:3px 8px; border-radius:4px; letter-spacing:1px;\">OPERACIONES ESPECIALES KO-HYOTEKI</span>\n      <div>\n        <h2 style=\"margin:0; font-family:'Cinzel', serif; font-size:1.35rem; color:#38bdf8; letter-spacing:1px; line-height:1.2;\">SENSUIKAN <span style=\"font-size:0.85rem; color:#94a3b8; font-weight:normal;\">(Submarinos de Flota Japoneses 1941\u201345)</span></h2>\n        <div style=\"font-size:0.86rem; color:#7dd3fc; font-weight:600;\">TABLAS M5, M6 Y M7: CONTACTOS, REDES DEFENSIVAS, EVENTOS Y RECUPERACI\u00d3N</div>\n      </div>\n    </div>\n    <span style=\"font-size:0.84rem; color:#94a3b8; background:rgba(0,0,0,0.4); padding:3px 8px; border-radius:4px; border:1px solid #334155;\">Oficial Compass Games</span>\n  </div>\n\n  <!-- CHART M5 -->\n  <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; margin-bottom:14px; border-top:3px solid #38bdf8;\">\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;\">\n      <h3 style=\"margin:0; font-size:1rem; color:#38bdf8; font-weight:800;\">TABLA [M5]: ENCUENTROS Y REDES ANTISUBMARINAS (CHART M5: ENCOUNTERS &amp; NET)</h3>\n      <span style=\"background:#0f172a; border:1px solid #64748b; color:#38bdf8; font-size:0.86rem; font-weight:bold; padding:2px 8px; border-radius:4px;\">\ud83c\udfb2 2d6</span>\n    </div>\n\n    <div style=\"display:grid; grid-template-columns: repeat(3, 1fr); gap:12px; font-size:0.84rem;\">\n      <!-- Transit Circle -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#7dd3fc; font-weight:bold; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px; text-align:center;\">C\u00edrculo de Tr\u00e1nsito </div>\n        <table style=\"width:100%; border-collapse:collapse; text-align:center;\">\n          <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:35px;\">Tirada</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Encuentro</th></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">2</td><td style=\"color:#f87171; font-weight:bold;\">Aviaci\u00f3n </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">3</td><td style=\"color:#64748b;\">-- (Sin contacto)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">4</td><td style=\"color:#fdba74;\">Evento Especial [M6]</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">5\u20136</td><td style=\"color:#64748b;\">-- (Sin contacto)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">7</td><td style=\"color:#fdba74;\">Evento Especial [M6]</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">8\u20139</td><td style=\"color:#64748b;\">-- (Sin contacto)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">10</td><td style=\"color:#fdba74;\">Evento Especial [M6]</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">11</td><td style=\"color:#64748b;\">-- (Sin contacto)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">12</td><td style=\"color:#f87171; font-weight:bold;\">Buque de Guerra </td></tr>\n        </table>\n      </div>\n\n      <!-- Target Circle -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#7dd3fc; font-weight:bold; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px; text-align:center;\">C\u00edrculo del Blanco / Puerto </div>\n        <table style=\"width:100%; border-collapse:collapse; text-align:center;\">\n          <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:35px;\">Tirada</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Encuentro</th></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">2</td><td style=\"color:#93c5fd;\">1 Buque </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">3</td><td style=\"color:#93c5fd;\">2x Buques </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">4</td><td style=\"color:#93c5fd;\">1 Buque Peque\u00f1o, 1 Buque </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">5</td><td style=\"color:#fdba74;\">1 Buque de Guerra, 1 Buque </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">6</td><td style=\"color:#93c5fd;\">3x Buques </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">7\u20138</td><td style=\"color:#fdba74;\">1 Buque de Guerra, 2x Buques </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">9</td><td style=\"color:#fdba74;\">1 Buque de Guerra, 3x Buques </td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">10</td><td style=\"color:#fde047; font-weight:bold;\">1 Buque Capital, 1 Buque de Guerra</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">11</td><td style=\"color:#fde047; font-weight:bold;\">1 Buque Capital, 2x Buques de Guerra</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">12</td><td style=\"color:#f87171; font-weight:bold;\">3x Buques Capitales </td></tr>\n        </table>\n      </div>\n\n      <!-- Anti-Sub Net -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#7dd3fc; font-weight:bold; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px; text-align:center;\">Red Antisubmarina </div>\n        <table style=\"width:100%; border-collapse:collapse; font-size:0.82rem;\">\n          <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:30px; text-align:center;\">2d6</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Resultado del Franqueo</th></tr>\n          <tr style=\"border-bottom:1px solid #1e293b;\"><td style=\"color:#ef4444; font-weight:bold; text-align:center;\">2</td><td style=\"color:#f87171;\"><strong>Atrapado Sin Esperanza :</strong> \u00a1Grito de Banzai al Emperador y Seppuku! Misi\u00f3n fallida.</td></tr>\n          <tr style=\"border-bottom:1px solid #1e293b;\"><td style=\"color:#fdba74; font-weight:bold; text-align:center;\">3</td><td style=\"color:#fde047;\"><strong>Atrapado :</strong> Detectado por patrullera ASV. Vuelve a tirar con -1 DRM.</td></tr>\n          <tr style=\"border-bottom:1px solid #1e293b;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">4</td><td style=\"color:#e2e8f0;\"><strong>A Trav\u00e9s de la Red :</strong> Tira detecci\u00f3n por patrulleras ASV. <em>(Si la dotaci\u00f3n tiene la habilidad de escuela <strong>Boat Handling</strong>, franquea la red limpiamente sin tirada).</em></td></tr>\n          <tr><td style=\"color:#4ade80; font-weight:bold; text-align:center;\">5\u201312</td><td style=\"color:#a7f3d0;\"><strong>A Trav\u00e9s de la Red :</strong> Franquea la red sin problemas.</td></tr>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- BOTTOM: CHART M6 & CHART M7 -->\n  <div style=\"display:grid; grid-template-columns: 1fr 1fr; gap:14px;\">\n    <!-- CHART M6 -->\n    <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; border-top:3px solid #38bdf8;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n        <h3 style=\"margin:0; font-size:0.95rem; color:#38bdf8; font-weight:800;\">TABLA [M6]: EVENTOS DE MINISUBMARINOS (CHART M6: MIDGET SUB EVENTS)</h3>\n        <span style=\"background:#0f172a; border:1px solid #64748b; color:#38bdf8; font-size:0.84rem; font-weight:bold; padding:2px 6px; border-radius:4px;\">\ud83c\udfb2 2d6</span>\n      </div>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.82rem;\">\n        <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:28px; text-align:center;\">2d6</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Evento Oficial</th></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">2</td><td><strong style=\"color:#f87171;\">Varada :</strong> El minisubmarino choca contra un obst\u00e1culo no cartografiado. Sufre 1 punto de da\u00f1o en el Casco (Hull) y tira 2 impactos adicionales.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">3</td><td><strong style=\"color:#fdba74;\">Interceptaci\u00f3n Ultra:</strong> Criptoanalistas descifradores de c\u00f3digos han advertido a las fuerzas aliadas del inminente ataque. Trata cualquier encuentro con Buques Capitales como sin encuentro.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">4</td><td><strong style=\"color:#fde047;\">Salida Accidental a Superficie :</strong> El minisubmarino emerge accidentalmente de forma temporal. Tira 2d6 para detecci\u00f3n: con 10+, es destruido por bater\u00edas costeras o buques ASV.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">5</td><td><strong style=\"color:#e2e8f0;\">Aver\u00eda :</strong> Tira 1 punto aleatorio de da\u00f1o y apl\u00edcalo de inmediato.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">6</td><td><strong style=\"color:#38bdf8;\">V\u00eda de Agua :</strong> Marca 1 casilla de inundaci\u00f3n (Flooding). No se produce casilla adicional de inundaci\u00f3n.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">7\u20138</td><td><strong style=\"color:#a7f3d0;\">Desorientado Moment\u00e1neamente :</strong> Pasa 1 turno adicional en el c\u00edrculo actual de tr\u00e1nsito o del objetivo.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">9</td><td><strong style=\"color:#38bdf8;\">Cartas de Navegaci\u00f3n Superiores:</strong> Concede +1 DRM en la Tabla [M7] para la recuperaci\u00f3n por el submarino nodriza.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">10</td><td><strong style=\"color:#22c55e;\">Maniobra Perfecta (Perfect Boat Handling):</strong> Mu\u00e9vete de inmediato al c\u00edrculo de tr\u00e1nsito o del objetivo que elijas. Ignora cualquier red antisubmarina o comprobaci\u00f3n de bucle de detecci\u00f3n.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">11</td><td><strong style=\"color:#22c55e;\">Torpedos Superiores :</strong> No realizas comprobaciones de torpedo inerte (Dud) en esta misi\u00f3n. Si ya disparaste tus torpedos, ignora este evento.</td></tr>\n        <tr><td style=\"color:#fde047; font-weight:bold; text-align:center;\">12</td><td><strong style=\"color:#f87171;\">Patrullera ASV Cercana:</strong> Tira detecci\u00f3n en Chart [B4] a distancia media (Medium Range), sin modificadores salvo el a\u00f1o. Si eres detectado, sufres ataque de escolta normal. Si no, contin\u00faa o aborta.</td></tr>\n      </table>\n    </div>\n\n    <!-- CHART M7 -->\n    <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; border-top:3px solid #10b981;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n        <h3 style=\"margin:0; font-size:0.95rem; color:#10b981; font-weight:800;\">TABLA [M7]: RECUPERACI\u00d3N DE MINISUBMARINO (MIDGET SUB RECOVERY)</h3>\n        <span style=\"background:#0f172a; border:1px solid #64748b; color:#10b981; font-size:0.84rem; font-weight:bold; padding:2px 6px; border-radius:4px;\">\ud83c\udfb2 1d6</span>\n      </div>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.86rem; margin-top:4px;\">\n        <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:45px; text-align:center;\">1d6</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Resultado Oficial</th></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#ef4444; font-weight:bold; text-align:center; font-size:1rem;\">1\u20133</td><td style=\"color:#f87171; padding:8px 4px;\"><strong>Perdido :</strong> El minisubmarino no logra conectar con el nodriza y se pierde en el mar (tripulaci\u00f3n capturada o KIA).</td></tr>\n        <tr><td style=\"color:#22c55e; font-weight:bold; text-align:center; font-size:1rem;\">4\u20136</td><td style=\"color:#a7f3d0; padding:8px 4px;\"><strong>Recuperado por el Submarino Nodriza :</strong> Amarre e izado con \u00e9xito a bordo. Dotaci\u00f3n salvada.</td></tr>\n      </table>\n      <div style=\"margin-top:14px; font-size:0.82rem; color:#f1f5f9; background:rgba(0,0,0,0.3); border:1px solid #334155; border-radius:6px; padding:8px; line-height:1.45;\">\n        <div style=\"color:var(--gold-300); font-weight:bold; margin-bottom:4px;\">Modificadores Oficiales a la tirada (DRM):</div>\n        <div>\u2022 <strong>+1 DRM</strong> si se posee la habilidad de escuela <strong>Superior Comms</strong> (Comunicaciones Superiores de Chart [F2]).</div>\n        <div>\u2022 <strong>+1 DRM</strong> adicional si se obtuvo el evento 9 de Chart [M6] (Cartas de navegaci\u00f3n superiores).</div>\n        <div>\u2022 <strong>-1 DRM</strong> por cada Radio fuera de servicio  en el Submarino Nodriza y/o en el Minisubmarino.</div>\n      </div>\n      <div style=\"margin-top:10px; font-size:0.78rem; color:#94a3b8; border-top:1px dashed #334155; padding-top:6px;\">\n        \ud83c\udf93 <strong>Conexi\u00f3n con Escuela [Chart F2]:</strong> En el curso de oficiales de F2 se tiran dos dados 1d6 en esta tabla M7. Si ambos obtienen 4\u20136 (ninguno falla), se gana la ficha <strong>Superior Comms</strong>, que otorga este +1 DRM permanente para todas las misiones.\n      </div>\n    </div>\n  </div>\n</div>\n        </div>\n        <!-- OCR TRANSCRIBED OFFICIAL CHARTS M8 & M9 -->\n        <div style=\"margin-bottom:16px;\">\n          <div class=\"ocr-board-m8-m9\" style=\"background:#0f172a; border:2px solid #38bdf8; border-radius:10px; padding:16px; color:#f1f5f9; font-family:'Segoe UI', Roboto, sans-serif; box-shadow:0 8px 30px rgba(0,0,0,0.7);\">\n  <!-- HEADER -->\n  <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid #38bdf8; padding-bottom:8px; margin-bottom:14px; flex-wrap:wrap; gap:10px;\">\n    <div style=\"display:flex; align-items:center; gap:12px;\">\n      <span style=\"background:#0284c7; color:#fff; font-size:0.86rem; font-weight:900; padding:3px 8px; border-radius:4px; letter-spacing:1px;\">OPERACIONES ESPECIALES KO-HYOTEKI</span>\n      <div>\n        <h2 style=\"margin:0; font-family:'Cinzel', serif; font-size:1.35rem; color:#38bdf8; letter-spacing:1px; line-height:1.2;\">SENSUIKAN <span style=\"font-size:0.85rem; color:#94a3b8; font-weight:normal;\">(Submarinos de Flota Japoneses 1941\u201345)</span></h2>\n        <div style=\"font-size:0.86rem; color:#7dd3fc; font-weight:600;\">TABLAS M8 Y M9: TABLA DE AVER\u00cdAS Y DESCRIPCI\u00d3N DE DA\u00d1OS DE MINISUBMARINOS</div>\n      </div>\n    </div>\n    <span style=\"font-size:0.84rem; color:#94a3b8; background:rgba(0,0,0,0.4); padding:3px 8px; border-radius:4px; border:1px solid #334155;\">Oficial Compass Games</span>\n  </div>\n\n  <!-- CHART M8: DAMAGE TABLE (d66) -->\n  <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; margin-bottom:14px; border-top:3px solid #ef4444;\">\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;\">\n      <h3 style=\"margin:0; font-size:1rem; color:#f87171; font-weight:800;\">TABLA [M8]: TABLA DE AVER\u00cdAS DE MINISUBMARINOS (CHART M8: MIDGET SUB DAMAGE TABLE)</h3>\n      <span style=\"background:#0f172a; border:1px solid #64748b; color:#f87171; font-size:0.86rem; font-weight:bold; padding:2px 8px; border-radius:4px;\">\ud83c\udfb2 1d6 Rojo (Decenas) + 1d6 Blanco (Unidades) = d66</span>\n    </div>\n\n    <div style=\"display:grid; grid-template-columns: repeat(6, 1fr); gap:8px; font-size:0.80rem;\">\n      <!-- Column 1 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">11\u201316</div>\n        <div><strong style=\"color:#fde047;\">11</strong> Inundaci\u00f3n</div>\n        <div><strong style=\"color:#fde047;\">12</strong> Tim\u00f3n Vertical</div>\n        <div><strong style=\"color:#94a3b8;\">13</strong> Da\u00f1o Menor</div>\n        <div><strong style=\"color:#fde047;\">14</strong> Tim\u00f3n Horiz.</div>\n        <div><strong style=\"color:#ef4444;\">15</strong> Casco (Hull)</div>\n        <div><strong style=\"color:#fde047;\">16</strong> H\u00e9lice (Propeller)</div>\n      </div>\n\n      <!-- Column 2 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">21\u201326</div>\n        <div><strong style=\"color:#fde047;\">21</strong> Inundaci\u00f3n</div>\n        <div><strong style=\"color:#94a3b8;\">22</strong> Da\u00f1o Menor</div>\n        <div><strong style=\"color:#ef4444;\">23</strong> Casco (Hull)</div>\n        <div><strong style=\"color:#38bdf8;\">24</strong> Motor El\u00e9ctrico</div>\n        <div><strong style=\"color:#38bdf8;\">25</strong> Motor El\u00e9ctrico</div>\n        <div><strong style=\"color:#38bdf8;\">26</strong> Bater\u00eda de Popa</div>\n      </div>\n\n      <!-- Column 3 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">31\u201336</div>\n        <div><strong style=\"color:#ef4444;\">31</strong> Casco (Hull)</div>\n        <div><strong style=\"color:#fca5a5;\">32</strong> Tripulaci\u00f3n</div>\n        <div><strong style=\"color:#fde047;\">33</strong> Periscopio</div>\n        <div><strong style=\"color:#fde047;\">34</strong> Inundaci\u00f3n</div>\n        <div><strong style=\"color:#94a3b8;\">35</strong> Da\u00f1o Menor</div>\n        <div><strong style=\"color:#fca5a5;\">36</strong> Tripulaci\u00f3n</div>\n      </div>\n\n      <!-- Column 4 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">41\u201346</div>\n        <div><strong style=\"color:#38bdf8;\">41</strong> Bater\u00eda Proa</div>\n        <div><strong style=\"color:#fde047;\">42</strong> Girocomp\u00e1s</div>\n        <div><strong style=\"color:#ef4444;\">43</strong> Casco (Hull)</div>\n        <div><strong style=\"color:#94a3b8;\">44</strong> Da\u00f1o Menor</div>\n        <div><strong style=\"color:#fca5a5;\">45</strong> Tripulaci\u00f3n</div>\n        <div><strong style=\"color:#fde047;\">46</strong> Inundaci\u00f3n</div>\n      </div>\n\n      <!-- Column 5 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">51\u201356</div>\n        <div><strong style=\"color:#38bdf8;\">51</strong> Hidr\u00f3fono</div>\n        <div><strong style=\"color:#94a3b8;\">52</strong> Da\u00f1o Menor</div>\n        <div><strong style=\"color:#fde047;\">53</strong> Inundaci\u00f3n</div>\n        <div><strong style=\"color:#fca5a5;\">54</strong> Tripulaci\u00f3n</div>\n        <div><strong style=\"color:#ef4444;\">55</strong> Casco (Hull)</div>\n        <div><strong style=\"color:#38bdf8;\">56</strong> Radio</div>\n      </div>\n\n      <!-- Column 6 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">61\u201366</div>\n        <div><strong style=\"color:#fde047;\">61</strong> Cortarredes</div>\n        <div><strong style=\"color:#f87171;\">62</strong> Tubo Torp. 1</div>\n        <div><strong style=\"color:#94a3b8;\">63</strong> Da\u00f1o Menor</div>\n        <div><strong style=\"color:#f87171;\">64</strong> Tubo Torp. 2</div>\n        <div><strong style=\"color:#fde047;\">65</strong> Inundaci\u00f3n</div>\n        <div><strong style=\"color:#ef4444;\">66</strong> Casco (Hull)</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CHART M9: DAMAGE LISTINGS (DETALLE OFICIAL DE SISTEMAS) -->\n  <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; border-top:3px solid #a855f7;\">\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;\">\n      <h3 style=\"margin:0; font-size:1rem; color:#c084fc; font-weight:800;\">TABLA [M9]: EFECTOS DE LAS AVER\u00cdAS (CHART M9: MIDGET SUB DAMAGE LISTINGS)</h3>\n      <span style=\"background:#0f172a; border:1px solid #64748b; color:#c084fc; font-size:0.86rem; font-weight:bold; padding:2px 8px; border-radius:4px;\">\ud83d\udccb Efectos &amp; Reparaciones (1d6)</span>\n    </div>\n\n    <div style=\"display:grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap:10px; font-size:0.80rem; line-height:1.4;\">\n      <!-- Flooding -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Inundaci\u00f3n (Flooding): \ud83c\udfb2 1d6</div>\n        <div>Marca una casilla. Si se marcan todas las casillas de inundaci\u00f3n, el minisubmarino debe emerger; comprueba si es echado a pique (Scuttling). Cada ronda con inundaci\u00f3n, marca una casilla adicional salvo que la tripulaci\u00f3n contenga la v\u00eda de agua.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">\u2022 1\u20134: Inundaci\u00f3n contenida (Halted)<br>\u2022 5\u20136: Casilla adicional de inundaci\u00f3n</div>\n        <div style=\"color:#a7f3d0; margin-top:2px;\">Tras el combate, la inundaci\u00f3n se repara por completo.</div>\n      </div>\n\n      <!-- Hull -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#ef4444; font-weight:bold; margin-bottom:4px;\">Casco (Hull):</div>\n        <div>Marca una casilla en la ficha de minisubmarino. Cuando se marcan todas las casillas de Casco, el minisubmarino es <strong>HUNDIDO (Sunk)</strong>.</div>\n        <div style=\"color:#f87171; margin-top:4px;\">\u26a0\ufe0f Los da\u00f1os en el casco NO son reparables en la mar.</div>\n      </div>\n\n      <!-- Torpedo Tubes -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#f87171; font-weight:bold; margin-bottom:4px;\">Tubos Lanzatorpedos (1 / 2):</div>\n        <div>El tubo correspondiente queda da\u00f1ado u obstruido y no puede ser disparado durante el resto de la misi\u00f3n.</div>\n      </div>\n\n      <!-- Gyrocompass -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Girocomp\u00e1s (Gyrocompass): \ud83c\udfb2 1d6</div>\n        <div>Si est\u00e1 da\u00f1ado: <strong>-3 DRM</strong> en la tirada de punto de cita y recuperaci\u00f3n [M7].</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Tira 1d6 tras el combate:<br>\u2022 1\u20132: Reparado (Fixed)<br>\u2022 3\u20136: Inoperativo (Inoperable)</div>\n      </div>\n\n      <!-- Batteries -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Bater\u00edas (Proa / Popa): \ud83c\udfb2 1d6</div>\n        <div>Sin efecto inmediato. Primer impacto: a partir de la ronda siguiente, <strong>+1 DRM</strong> a ser detectado por buques ASV y +1 en Tabla E3. Si ambas bater\u00edas quedan destruidas, debe emerger a superficie y echarse a pique.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Tira 1d6 tras combate: 1\u20134 Inoperativo, 5\u20136 Reparado.</div>\n      </div>\n\n      <!-- Periscope -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Periscopio: \ud83c\udfb2 1d6</div>\n        <div>No puede realizar ataques. Tras el combate, tira 1d6 una sola vez:</div>\n        <div style=\"margin-top:4px; color:#fde047;\">\u2022 1\u20134: Inoperativo (Inoperable)<br>\u2022 5\u20136: Reparado (Fixed)</div>\n      </div>\n\n      <!-- Electric Motor -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Motor El\u00e9ctrico: \ud83c\udfb2 1d6</div>\n        <div>Primer impacto: maniobrabilidad reducida, <strong>+1 DRM</strong> a ser detectado por ASV. Segundo impacto: <strong>+2 DRM</strong> adicional y +1/+2 en Tabla E3.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Tira 1d6 por motor tras combate: 1\u20132 Reparado, 3\u20136 Inoperativo.</div>\n      </div>\n\n      <!-- Hydrophones -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Hidr\u00f3fonos: \ud83c\udfb2 1d6</div>\n        <div>No puede realizar maniobras evasivas apropiadas: <strong>+1 DRM</strong> a ser detectado por ASV.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Tira 1d6 tras combate: 1\u20134 Inoperativo, 5\u20136 Reparado.</div>\n      </div>\n\n      <!-- Wire Cutter -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Cortarredes de Proa (Wire Cutter):</div>\n        <div>Si est\u00e1 da\u00f1ado: <strong>-3 DRM</strong> a la tirada de franqueo de redes antisubmarinas [M5].</div>\n        <div style=\"color:#f87171; margin-top:2px;\">No reparable en la mar.</div>\n      </div>\n\n      <!-- Rudders & Propeller -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Timones &amp; H\u00e9lice: \ud83c\udfb2 1d6</div>\n        <div>\u2022 <strong>Tim\u00f3n Horiz./Vert.:</strong> +1 detecci\u00f3n ASV, -1 a detectar defensas y tablas de encuentro. (Tras combate 1d6: 1\u20132 Reparado, 3\u20136 Inoperable).<br>\u2022 <strong>H\u00e9lice:</strong> +1 a toda detecci\u00f3n por ASV. No reparable.</div>\n      </div>\n\n      <!-- Radio -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Radio: \ud83c\udfb2 1d6</div>\n        <div>Aplica <strong>-1 DRM</strong> en la Tabla de Recuperaci\u00f3n [M7].</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Tira 1d6 tras combate: 1\u20132 Reparado, 3\u20136 No reparable.</div>\n      </div>\n\n      <!-- Crew Injury -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fca5a5; font-weight:bold; margin-bottom:4px;\">Baja de Dotaci\u00f3n: \ud83c\udfb2 1d6</div>\n        <div>Tira 1d6: 1\u20133 Oficial al mando, 4\u20136 Suboficial.<br>Vuelve a tirar 1d6 para gravedad:</div>\n        <div style=\"margin-top:4px; color:#fde047;\">\u2022 1\u20133: Herida Leve (LW, sin efecto en servicio)<br>\u2022 4\u20135: Herida Grave (SW)<br>\u2022 6: Muerto en Acci\u00f3n (KIA)</div>\n        <div style=\"color:#ef4444; margin-top:2px;\">(2x LW = SW; 2x SW = KIA). Si alg\u00fan tripulante sufre SW o KIA, la misi\u00f3n especial fracasa.</div>\n      </div>\n    </div>\n  </div>\n</div>\n        </div>\n      </div>",
  en: "<div id=\"comp-sec-midget\" class=\"compendium-section\" data-comp-sec=\"midget\" style=\"margin-bottom:28px;\">\n        <h3 style=\"border-bottom:2px solid #38bdf8; padding-bottom:6px; color:#38bdf8; font-family:'Cinzel', serif; font-size:1.15rem; display:flex; align-items:center; gap:8px;\">\n          <span>\u2693</span> <span>5. KO-HYOTEKI MIDGET SUBMARINE SPECIAL OPERATIONS (CHARTS M5 TO M9)</span>\n        </h3>\n\n        <!-- OCR TRANSCRIBED OFFICIAL CHARTS M5 TO M7 -->\n        <div style=\"margin-bottom:16px;\">\n          <div class=\"ocr-board-m5-m7\" style=\"background:#0f172a; border:2px solid #38bdf8; border-radius:10px; padding:16px; color:#f1f5f9; font-family:'Segoe UI', Roboto, sans-serif; box-shadow:0 8px 30px rgba(0,0,0,0.7);\">\n  <!-- HEADER -->\n  <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid #38bdf8; padding-bottom:8px; margin-bottom:14px; flex-wrap:wrap; gap:10px;\">\n    <div style=\"display:flex; align-items:center; gap:12px;\">\n      <span style=\"background:#0284c7; color:#fff; font-size:0.86rem; font-weight:900; padding:3px 8px; border-radius:4px; letter-spacing:1px;\">KO-HYOTEKI SPECIAL OPERATIONS</span>\n      <div>\n        <h2 style=\"margin:0; font-family:'Cinzel', serif; font-size:1.35rem; color:#38bdf8; letter-spacing:1px; line-height:1.2;\">SENSUIKAN <span style=\"font-size:0.85rem; color:#94a3b8; font-weight:normal;\">(Japanese Fleet Submarines 1941\u201345)</span></h2>\n        <div style=\"font-size:0.86rem; color:#7dd3fc; font-weight:600;\">CHARTS M5, M6 &amp; M7: CONTACTS, DEFENSIVE NETS, EVENTS &amp; RECOVERY</div>\n      </div>\n    </div>\n    <span style=\"font-size:0.84rem; color:#94a3b8; background:rgba(0,0,0,0.4); padding:3px 8px; border-radius:4px; border:1px solid #334155;\">Official Compass Games</span>\n  </div>\n\n  <!-- CHART M5 -->\n  <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; margin-bottom:14px; border-top:3px solid #38bdf8;\">\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;\">\n      <h3 style=\"margin:0; font-size:1rem; color:#38bdf8; font-weight:800;\">CHART [M5]: MIDGET SUB ENCOUNTERS &amp; NET</h3>\n      <span style=\"background:#0f172a; border:1px solid #64748b; color:#38bdf8; font-size:0.86rem; font-weight:bold; padding:2px 8px; border-radius:4px;\">\ud83c\udfb2 2d6</span>\n    </div>\n\n    <div style=\"display:grid; grid-template-columns: repeat(3, 1fr); gap:12px; font-size:0.84rem;\">\n      <!-- Transit Circle -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#7dd3fc; font-weight:bold; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px; text-align:center;\">Transit Circle (2d6)</div>\n        <table style=\"width:100%; border-collapse:collapse; text-align:center;\">\n          <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:35px;\">Roll</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Encounter</th></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">2</td><td style=\"color:#f87171; font-weight:bold;\">Aircraft</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">3</td><td style=\"color:#64748b;\">-- (No contact)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">4</td><td style=\"color:#fdba74;\">Event [M6]</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">5\u20136</td><td style=\"color:#64748b;\">-- (No contact)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">7</td><td style=\"color:#fdba74;\">Event [M6]</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">8\u20139</td><td style=\"color:#64748b;\">-- (No contact)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">10</td><td style=\"color:#fdba74;\">Event [M6]</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">11</td><td style=\"color:#64748b;\">-- (No contact)</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">12</td><td style=\"color:#f87171; font-weight:bold;\">Warship</td></tr>\n        </table>\n      </div>\n\n      <!-- Target Circle -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#7dd3fc; font-weight:bold; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px; text-align:center;\">Target Circle (2d6)</div>\n        <table style=\"width:100%; border-collapse:collapse; text-align:center;\">\n          <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:35px;\">Roll</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Encounter</th></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">2</td><td style=\"color:#93c5fd;\">Ship</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">3</td><td style=\"color:#93c5fd;\">2x Ships</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">4</td><td style=\"color:#93c5fd;\">Ship (S), Ship</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">5</td><td style=\"color:#fdba74;\">Warship, Ship</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">6</td><td style=\"color:#93c5fd;\">3x Ships</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">7\u20138</td><td style=\"color:#fdba74;\">Warship, 2x Ships</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">9</td><td style=\"color:#fdba74;\">Warship, 3x Ships</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">10</td><td style=\"color:#fde047; font-weight:bold;\">Capital Ship, Warship</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">11</td><td style=\"color:#fde047; font-weight:bold;\">Capital Ship, 2x Warships</td></tr>\n          <tr><td style=\"color:#fde047; font-weight:bold;\">12</td><td style=\"color:#f87171; font-weight:bold;\">3x Capital Ships</td></tr>\n        </table>\n      </div>\n\n      <!-- Anti-Sub Net -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#7dd3fc; font-weight:bold; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px; text-align:center;\">Anti-Sub Net (2d6)</div>\n        <table style=\"width:100%; border-collapse:collapse; font-size:0.82rem;\">\n          <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:30px; text-align:center;\">2d6</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Outcome</th></tr>\n          <tr style=\"border-bottom:1px solid #1e293b;\"><td style=\"color:#ef4444; font-weight:bold; text-align:center;\">2</td><td style=\"color:#f87171;\"><strong>Caught:</strong> Hopelessly caught. Give a Banzai to the Emperor and commit Seppuku.</td></tr>\n          <tr style=\"border-bottom:1px solid #1e293b;\"><td style=\"color:#fdba74; font-weight:bold; text-align:center;\">3</td><td style=\"color:#fde047;\"><strong>Caught:</strong> Detected by ASV. Roll again with -1 drm.</td></tr>\n          <tr style=\"border-bottom:1px solid #1e293b;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">4</td><td style=\"color:#e2e8f0;\"><strong>Through:</strong> Roll for Detect. by ASV. <em>(If crew has school skill <strong>Boat Handling</strong>, passes cleanly without detection roll).</em></td></tr>\n          <tr><td style=\"color:#4ade80; font-weight:bold; text-align:center;\">5\u201312</td><td style=\"color:#a7f3d0;\"><strong>Through:</strong> Passes through net without incident.</td></tr>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- BOTTOM: CHART M6 & CHART M7 -->\n  <div style=\"display:grid; grid-template-columns: 1fr 1fr; gap:14px;\">\n    <!-- CHART M6 -->\n    <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; border-top:3px solid #38bdf8;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n        <h3 style=\"margin:0; font-size:0.95rem; color:#38bdf8; font-weight:800;\">CHART [M6]: MIDGET SUB EVENTS</h3>\n        <span style=\"background:#0f172a; border:1px solid #64748b; color:#38bdf8; font-size:0.84rem; font-weight:bold; padding:2px 6px; border-radius:4px;\">\ud83c\udfb2 2d6</span>\n      </div>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.82rem;\">\n        <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:28px; text-align:center;\">2d6</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Official Event</th></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">2</td><td><strong style=\"color:#f87171;\">Run Aground:</strong> Midget sub hits an uncharted obstacle. Take 1 hull damage and roll 2 hits.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">3</td><td><strong style=\"color:#fdba74;\">Ultra Intercept:</strong> Code-breakers have warned Allied Forces of your impending attack. Treat any Capital Ship encounters as no encounter.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">4</td><td><strong style=\"color:#fde047;\">Broached:</strong> Your Midget Sub temporarily accidentally surfaces. Roll for detection 2d6: on a roll of 10+ your Midget Sub is destroyed by Shore Batteries or an ASV.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">5</td><td><strong style=\"color:#e2e8f0;\">Malfunction:</strong> Roll for 1 random point of damage and apply immediately.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">6</td><td><strong style=\"color:#38bdf8;\">Leak:</strong> Take a single box of flooding. An additional box of flooding does not occur.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">7\u20138</td><td><strong style=\"color:#a7f3d0;\">Momentarily Lost:</strong> Spend an additional turn in your current transit or target circle.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">9</td><td><strong style=\"color:#38bdf8;\">Superior Navigation Charts:</strong> +1 on [M7] for Recovery by Mother submarine.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">10</td><td><strong style=\"color:#22c55e;\">Perfect Boat Handling:</strong> Immediately move to the transit or target circle of your choice. Disregard any anti-submarine net or detection loop checks.</td></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#fde047; font-weight:bold; text-align:center;\">11</td><td><strong style=\"color:#22c55e;\">Superior Torpedoes:</strong> You do not make any Dud checks for this mission. If you have already fired your torpedoes, ignore this event.</td></tr>\n        <tr><td style=\"color:#fde047; font-weight:bold; text-align:center;\">12</td><td><strong style=\"color:#f87171;\">ASV Nearby:</strong> Roll for Detection on chart [B4] as if you had just attacked from Medium Range, with no modifiers other than the year. If detected, undergo attack per the normal game rules. Anti-Submarine Vessels (ASV) are treated as Escorts for all game purposes. Once undetected, you may continue on the mission or abort if desired.</td></tr>\n      </table>\n    </div>\n\n    <!-- CHART M7 -->\n    <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; border-top:3px solid #10b981;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n        <h3 style=\"margin:0; font-size:0.95rem; color:#10b981; font-weight:800;\">CHART [M7]: MIDGET SUB RECOVERY</h3>\n        <span style=\"background:#0f172a; border:1px solid #64748b; color:#10b981; font-size:0.84rem; font-weight:bold; padding:2px 6px; border-radius:4px;\">\ud83c\udfb2 1d6</span>\n      </div>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.86rem; margin-top:4px;\">\n        <tr style=\"border-bottom:1px solid #1e293b;\"><th style=\"color:#94a3b8; font-size:0.75rem; width:45px; text-align:center;\">1d6</th><th style=\"color:#94a3b8; font-size:0.75rem;\">Official Result</th></tr>\n        <tr style=\"border-bottom:1px solid #334155;\"><td style=\"color:#ef4444; font-weight:bold; text-align:center; font-size:1rem;\">1\u20133</td><td style=\"color:#f87171; padding:8px 4px;\"><strong>Lost:</strong> Midget Sub fails to rendezvous with Mother Sub and is lost at sea (crew captured or KIA).</td></tr>\n        <tr><td style=\"color:#22c55e; font-weight:bold; text-align:center; font-size:1rem;\">4\u20136</td><td style=\"color:#a7f3d0; padding:8px 4px;\"><strong>Recovered by Mother Sub:</strong> Successfully moored and hoisted aboard. Crew saved.</td></tr>\n      </table>\n      <div style=\"margin-top:14px; font-size:0.82rem; color:#f1f5f9; background:rgba(0,0,0,0.3); border:1px solid #334155; border-radius:6px; padding:8px; line-height:1.45;\">\n        <div style=\"color:var(--gold-300); font-weight:bold; margin-bottom:4px;\">Official Die Roll Modifiers (DRM):</div>\n        <div>\u2022 <strong>+1 drm</strong> for <strong>Superior Comms</strong> (from School Chart [F2]).</div>\n        <div>\u2022 <strong>+1 drm</strong> for Superior Navigation Charts (Event 9 on Chart [M6]).</div>\n        <div>\u2022 <strong>-1 drm</strong> per Inop Radio (Mother Sub and/or Midget Sub).</div>\n      </div>\n      <div style=\"margin-top:10px; font-size:0.78rem; color:#94a3b8; border-top:1px dashed #334155; padding-top:6px;\">\n        \ud83c\udf93 <strong>Connection with School [Chart F2]:</strong> In F2 Officers Course, roll twice on this table M7. If neither fails (both roll 4\u20136), you gain the <strong>Superior Comms</strong> marker, which grants this permanent +1 drm for all missions.\n      </div>\n    </div>\n  </div>\n</div>\n        </div>\n\n        <!-- OCR TRANSCRIBED OFFICIAL CHARTS M8 & M9 -->\n        <div style=\"margin-bottom:16px;\">\n          <div class=\"ocr-board-m8-m9\" style=\"background:#0f172a; border:2px solid #38bdf8; border-radius:10px; padding:16px; color:#f1f5f9; font-family:'Segoe UI', Roboto, sans-serif; box-shadow:0 8px 30px rgba(0,0,0,0.7);\">\n  <!-- HEADER -->\n  <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid #38bdf8; padding-bottom:8px; margin-bottom:14px; flex-wrap:wrap; gap:10px;\">\n    <div style=\"display:flex; align-items:center; gap:12px;\">\n      <span style=\"background:#0284c7; color:#fff; font-size:0.86rem; font-weight:900; padding:3px 8px; border-radius:4px; letter-spacing:1px;\">KO-HYOTEKI SPECIAL OPERATIONS</span>\n      <div>\n        <h2 style=\"margin:0; font-family:'Cinzel', serif; font-size:1.35rem; color:#38bdf8; letter-spacing:1px; line-height:1.2;\">SENSUIKAN <span style=\"font-size:0.85rem; color:#94a3b8; font-weight:normal;\">(Japanese Fleet Submarines 1941\u201345)</span></h2>\n        <div style=\"font-size:0.86rem; color:#7dd3fc; font-weight:600;\">CHARTS M8 &amp; M9: MIDGET SUB DAMAGE TABLE &amp; DAMAGE LISTINGS</div>\n      </div>\n    </div>\n    <span style=\"font-size:0.84rem; color:#94a3b8; background:rgba(0,0,0,0.4); padding:3px 8px; border-radius:4px; border:1px solid #334155;\">Official Compass Games</span>\n  </div>\n\n  <!-- CHART M8: DAMAGE TABLE (d66) -->\n  <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; margin-bottom:14px; border-top:3px solid #ef4444;\">\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;\">\n      <h3 style=\"margin:0; font-size:1rem; color:#f87171; font-weight:800;\">CHART [M8]: MIDGET SUB DAMAGE TABLE</h3>\n      <span style=\"background:#0f172a; border:1px solid #64748b; color:#f87171; font-size:0.86rem; font-weight:bold; padding:2px 8px; border-radius:4px;\">\ud83c\udfb2 1d6 Red (Tens) + 1d6 White (Units) = d66</span>\n    </div>\n\n    <div style=\"display:grid; grid-template-columns: repeat(6, 1fr); gap:8px; font-size:0.80rem;\">\n      <!-- Column 1 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">11\u201316</div>\n        <div><strong style=\"color:#fde047;\">11</strong> Flooding</div>\n        <div><strong style=\"color:#fde047;\">12</strong> Vertical Rudder</div>\n        <div><strong style=\"color:#94a3b8;\">13</strong> Minor Damage</div>\n        <div><strong style=\"color:#fde047;\">14</strong> Horiz. Rudder</div>\n        <div><strong style=\"color:#ef4444;\">15</strong> Hull</div>\n        <div><strong style=\"color:#fde047;\">16</strong> Propeller</div>\n      </div>\n\n      <!-- Column 2 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">21\u201326</div>\n        <div><strong style=\"color:#fde047;\">21</strong> Flooding</div>\n        <div><strong style=\"color:#94a3b8;\">22</strong> Minor Damage</div>\n        <div><strong style=\"color:#ef4444;\">23</strong> Hull</div>\n        <div><strong style=\"color:#38bdf8;\">24</strong> Electric Motor</div>\n        <div><strong style=\"color:#38bdf8;\">25</strong> Electric Motor</div>\n        <div><strong style=\"color:#38bdf8;\">26</strong> Aft Battery</div>\n      </div>\n\n      <!-- Column 3 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">31\u201336</div>\n        <div><strong style=\"color:#ef4444;\">31</strong> Hull</div>\n        <div><strong style=\"color:#fca5a5;\">32</strong> Crew</div>\n        <div><strong style=\"color:#fde047;\">33</strong> Periscope</div>\n        <div><strong style=\"color:#fde047;\">34</strong> Flooding</div>\n        <div><strong style=\"color:#94a3b8;\">35</strong> Minor Damage</div>\n        <div><strong style=\"color:#fca5a5;\">36</strong> Crew</div>\n      </div>\n\n      <!-- Column 4 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">41\u201346</div>\n        <div><strong style=\"color:#38bdf8;\">41</strong> Fwd. Battery</div>\n        <div><strong style=\"color:#fde047;\">42</strong> Gyrocompass</div>\n        <div><strong style=\"color:#ef4444;\">43</strong> Hull</div>\n        <div><strong style=\"color:#94a3b8;\">44</strong> Minor Damage</div>\n        <div><strong style=\"color:#fca5a5;\">45</strong> Crew</div>\n        <div><strong style=\"color:#fde047;\">46</strong> Flooding</div>\n      </div>\n\n      <!-- Column 5 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">51\u201356</div>\n        <div><strong style=\"color:#38bdf8;\">51</strong> Hydrophone</div>\n        <div><strong style=\"color:#94a3b8;\">52</strong> Minor Damage</div>\n        <div><strong style=\"color:#fde047;\">53</strong> Flooding</div>\n        <div><strong style=\"color:#fca5a5;\">54</strong> Crew</div>\n        <div><strong style=\"color:#ef4444;\">55</strong> Hull</div>\n        <div><strong style=\"color:#38bdf8;\">56</strong> Radio</div>\n      </div>\n\n      <!-- Column 6 -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:4px; padding:6px;\">\n        <div style=\"color:#ef4444; font-weight:bold; border-bottom:1px solid #334155; text-align:center; padding-bottom:3px; margin-bottom:4px;\">61\u201366</div>\n        <div><strong style=\"color:#fde047;\">61</strong> Wire Cutter</div>\n        <div><strong style=\"color:#f87171;\">62</strong> Torp. Tube 1</div>\n        <div><strong style=\"color:#94a3b8;\">63</strong> Minor Damage</div>\n        <div><strong style=\"color:#f87171;\">64</strong> Torp. Tube 2</div>\n        <div><strong style=\"color:#fde047;\">65</strong> Flooding</div>\n        <div><strong style=\"color:#ef4444;\">66</strong> Hull</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CHART M9: DAMAGE LISTINGS (DETALLE OFICIAL DE SISTEMAS) -->\n  <div style=\"background:#1e293b; border:1px solid #475569; border-radius:8px; padding:12px; border-top:3px solid #a855f7;\">\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;\">\n      <h3 style=\"margin:0; font-size:1rem; color:#c084fc; font-weight:800;\">CHART [M9]: MIDGET SUB DAMAGE LISTINGS</h3>\n      <span style=\"background:#0f172a; border:1px solid #64748b; color:#c084fc; font-size:0.86rem; font-weight:bold; padding:2px 8px; border-radius:4px;\">\ud83d\udccb Effects &amp; Repairs (1d6)</span>\n    </div>\n\n    <div style=\"display:grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap:10px; font-size:0.80rem; line-height:1.4;\">\n      <!-- Flooding -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Flooding: \ud83c\udfb2 1d6</div>\n        <div>Mark off one box. If all boxes are checked off, the Sub must surface. Check for Scuttling. On any round flooding has occurred, one additional flooding box is checked off IF the Crew fails to halt the Flooding.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">\u2022 1\u20134: Flooding Halted<br>\u2022 5\u20136: Additional Flooding</div>\n        <div style=\"color:#a7f3d0; margin-top:2px;\">After combat, Flooding is completely removed.</div>\n      </div>\n\n      <!-- Hull -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#ef4444; font-weight:bold; margin-bottom:4px;\">Hull:</div>\n        <div>Mark off one box on the Midget Sub mat. When all boxes are checked off, the Midget Sub is sunk.</div>\n        <div style=\"color:#f87171; margin-top:4px;\">\u26a0\ufe0f Hull damage is not repairable at sea.</div>\n      </div>\n\n      <!-- Torpedo Tubes -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#f87171; font-weight:bold; margin-bottom:4px;\">Torpedo Tubes (1 / 2):</div>\n        <div>Torpedo tube is damaged or obstructed and cannot be used for the rest of the Mission.</div>\n      </div>\n\n      <!-- Gyrocompass -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Gyrocompass: \ud83c\udfb2 1d6</div>\n        <div>If Gyrocompass is damaged, <strong>-3 on Rendezvous / Recovery roll [M7]</strong>.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Roll 1d6 after combat:<br>\u2022 1\u20132: Fixed<br>\u2022 3\u20136: Inoperable</div>\n      </div>\n\n      <!-- Batteries -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Batteries (Fwd. / Aft): \ud83c\udfb2 1d6</div>\n        <div>No immediate effect. First hit, starting with the next round, <strong>+1 DRM</strong> to be detected by ASV. +1 on Table E3. If both batteries are destroyed, Midget Sub must surface. Check for Scuttling.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Roll 1d6 after combat: 1\u20134 Inoperable, 5\u20136 Fixed.</div>\n      </div>\n\n      <!-- Periscope -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Periscope: \ud83c\udfb2 1d6</div>\n        <div>Cannot make attacks. After combat is complete, roll 1d6 once to fix:</div>\n        <div style=\"margin-top:4px; color:#fde047;\">\u2022 1\u20134: Inoperable<br>\u2022 5\u20136: Fixed</div>\n      </div>\n\n      <!-- Electric Motor -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Electric Motor: \ud83c\udfb2 1d6</div>\n        <div>First Motor hit, the Sub cannot maneuver as well, so <strong>+1</strong> to be detected by ASV. On second Motor hit, apply a <strong>+2</strong>. Plus +1/+2 on Table E3.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Roll 1d6 once for each engine/motor after combat: 1\u20132 Fixed, 3\u20136 Non-repairable.</div>\n      </div>\n\n      <!-- Hydrophones -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Hydrophones: \ud83c\udfb2 1d6</div>\n        <div>Cannot take proper evasive action; <strong>+1</strong> to be detected by ASV.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Roll 1d6 after combat: 1\u20134 Inoperable, 5\u20136 Fixed.</div>\n      </div>\n\n      <!-- Wire Cutter -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Wire Cutter:</div>\n        <div>If the wire-cutter is damaged, <strong>-3 to Anti-Submarine net roll [M5]</strong>.</div>\n        <div style=\"color:#f87171; margin-top:2px;\">Not repairable at sea.</div>\n      </div>\n\n      <!-- Rudders & Propeller -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fde047; font-weight:bold; margin-bottom:4px;\">Vert./Horiz. Rudder &amp; Propeller: \ud83c\udfb2 1d6</div>\n        <div>\u2022 <strong>Vert./Horiz. Rudder:</strong> +1 to be detected by ASV, -1 on any roll to detect local defenses, -1 on Encounter tables. (After combat 1d6: 1\u20132 Fixed, 3\u20136 Non-repairable).<br>\u2022 <strong>Propeller:</strong> If hit, apply +1 to all ASV detection rolls. Not repairable.</div>\n      </div>\n\n      <!-- Radio -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#38bdf8; font-weight:bold; margin-bottom:4px;\">Radio: \ud83c\udfb2 1d6</div>\n        <div><strong>-1 to Recovery Roll [M7]</strong>.</div>\n        <div style=\"margin-top:4px; color:#fde047;\">Roll 1d6 after combat: 1\u20132 Fixed, 3\u20136 Non-repairable.</div>\n      </div>\n\n      <!-- Crew Injury -->\n      <div style=\"background:#0f172a; border:1px solid #334155; border-radius:6px; padding:8px;\">\n        <div style=\"color:#fca5a5; font-weight:bold; margin-bottom:4px;\">Crew Injury: \ud83c\udfb2 1d6</div>\n        <div>Roll 1d6: 1\u20133 Officer, 4\u20136 Petty Officer.<br>Roll again, 1d6:</div>\n        <div style=\"margin-top:4px; color:#fde047;\">\u2022 1\u20133: Light Wound (LW, no effect on duty)<br>\u2022 4\u20135: Serious Wound (SW)<br>\u2022 6: Killed in Action (KIA)</div>\n        <div style=\"color:#ef4444; margin-top:2px;\">(2x LW = SW; 2x SW = KIA). If either crewman SW/KIA, Special Mission fails.</div>\n      </div>\n    </div>\n  </div>\n</div>\n        </div>\n      </div>"
};
